public class Probe { static class Impl extends GenericAbstractReceiverProbe { public <T extends Number> T target(T value) { return value; } } public static void main(String[] args) throws Exception { java.lang.reflect.Method m=GenericAbstractReceiverProbe.class.getDeclaredMethod("target",Number.class); java.lang.reflect.TypeVariable<?> t=m.getTypeParameters()[0]; System.out.print(GenericAbstractReceiverProbe.call(new Impl())+":"+new Impl().own()+":"+t.getGenericDeclaration().equals(m)+":"+m.getGenericReturnType().equals(t)+":"+m.getGenericParameterTypes()[0].equals(t)+":"+java.util.Arrays.toString(t.getBounds())); } }
